const state={scenario:'couple',sort:'rating',collections:new Set(),regions:new Set(),meals:new Set(['none','breakfast','halfboard','fullboard']),wellness:new Set(),maxTotal:Infinity,data:null};
const money=n=>Number.isFinite(n)?new Intl.NumberFormat('uk-UA').format(Math.round(n))+' ₴':'уточнюється';
const dateTimeFmt=s=>s?new Intl.DateTimeFormat('uk-UA',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit',hour12:false,timeZone:'Europe/Kyiv'}).format(new Date(s)):'—';
const humanize=t=>String(t??'').replaceAll('indoor-дозвілля','розваги в приміщенні').replaceAll('value-кандидатів','варіантів').replaceAll('сімейний value','співвідношення ціни та сімейних можливостей').replaceAll('осіння придатність','придатність для відпочинку наприкінці жовтня');
const heroImages={'kyivska-russ':{src:'https://kyivskaruss.com.ua/wp-content/uploads/2026/02/q11.jpg.webp',alt:'Kyivska Russ Resort Medical & Spa',source:'Офіційний сайт'}};
function oblastOf(h){const s=`${h.region||''} ${h.location||''}`;const names=['Закарпатська','Івано-Франківська','Львівська','Чернівецька','Хмельницька','Тернопільська','Волинська','Житомирська','Черкаська','Рівненська','Київська','Вінницька'];const found=names.find(x=>s.includes(x));return found?`${found} область`:(h.region?.includes('область')?h.region:'Інша область')}
function mealClass(v){const s=(v?.meals||'').toLowerCase();if(!s)return null;if(s.includes('без харч')||s==='ro')return'none';if(s.includes('трираз')||s.includes('3-раз')||s.includes('3 раз')||s.includes('сніданок')&&s.includes('обід')&&s.includes('вечер'))return'fullboard';if(s.includes('двораз')||s.includes('2-раз')||s.includes('2 раз')||s.includes('сніданок')&&s.includes('вечер'))return'halfboard';if(s.includes('снідан'))return'breakfast';if(s.includes('однораз')||s.includes('1-раз')||s.includes('1 раз')||s.includes('one meal')||s.includes('обід')||s.includes('вечер'))return'onemeal';return null}
function tagsOf(h){const tags=new Set(h.categories||h.collections||[]);if(h.rareFind)tags.add('rareFind');if(h.bestSpa)tags.add('bestSpa');if(h.mountainStay||h.mountain)tags.add('mountain');if(h.forKids||h.childFriendly)tags.add('forKids');return tags}
function featureState(h,key){const f=h.features||h.wellness||{};if(Object.prototype.hasOwnProperty.call(f,key))return f[key]===true?'yes':f[key]===false?'no':'unknown';if(key==='pool'&&typeof h.indoorSpa==='boolean')return h.indoorSpa?'yes':'no';return'unknown'}
function valueNum(v){const m=String(v?.value||'').match(/[0-9]+(?:[.,][0-9]+)?/);return m?Number(m[0].replace(',','.')):null}
function scenarioBase(h){return state.scenario==='couple'?h.couple:h.family}
function scenarioOffers(h){const base=scenarioBase(h);if(!base)return[];const scenarioKey=state.scenario;const raw=[...(base.offers||[]),...(h.offers||[]).filter(o=>!o.scenario||o.scenario===scenarioKey)];const explicit=raw.map(o=>{const merged={...base,...o,_isExplicitOffer:true};if(!Object.prototype.hasOwnProperty.call(o,'value'))delete merged.value;return merged});return[{...base,_isExplicitOffer:false},...explicit]}
function selectedView(h){const offers=scenarioOffers(h).filter(v=>v?.eligible!==false);const compatible=offers.filter(v=>{const mc=mealClass(v);return mc&&state.meals.has(mc)});if(compatible.length)return compatible.sort((a,b)=>((a.total7Nights??Infinity)-(b.total7Nights??Infinity)))[0];return null}
function heroLoads(h){const info=photoInfo(h);if(!info?.src)return Promise.resolve(false);return new Promise(resolve=>{const im=new Image();let done=false;const finish=v=>{if(done)return;done=true;clearTimeout(timer);resolve(v)};const timer=setTimeout(()=>finish(false),5000);im.onload=()=>finish(im.naturalWidth>1&&im.naturalHeight>1);im.onerror=()=>finish(false);im.src=info.src})}
async function load(){const [baseRes,extraRes]=await Promise.all([fetch('hotels.json',{cache:'no-store'}),fetch('hotels-20260914.json',{cache:'no-store'}).catch(()=>null)]);if(!baseRes.ok)throw new Error(`hotels.json: HTTP ${baseRes.status}`);const base=await baseRes.json(),extra=extraRes?.ok?await extraRes.json():null;const byId=new Map(base.hotels.map(h=>[h.id,h]));(extra?.hotels||[]).forEach(h=>byId.set(h.id,h));const aliasFamilies=[['solva-resort-medical-spa','solva'],['chervona-ruta-shayan','chervona-ruta'],['taor-karpaty','taor'],['vedmezha-gora-yaremche','vedmezha-gora']];for(const [canonical,legacy] of aliasFamilies){if(byId.has(canonical))byId.delete(legacy)}let hotels=[...byId.values()];const newHotels=hotels.filter(h=>String(h.checkedAt||'')>='2026-09-20');newHotels.forEach(h=>heroLoads(h).catch(()=>false));state.data={...base,hotels,meta:{...base.meta,...(extra?.meta||{})}};document.getElementById('updatedAt').textContent=dateTimeFmt(state.data.meta.updatedAt);document.getElementById('auditState').textContent='Дані оновлюються за змістовними перевірками';initRegions();bind();render()}
function initRegions(){const root=document.getElementById('regionButtons');const regions=[...new Set(state.data.hotels.map(oblastOf))].sort((a,b)=>a.localeCompare(b,'uk'));regions.forEach(r=>state.regions.add(r));root.innerHTML=regions.map(r=>`<button class="toggle-btn active" data-region="${r}">✓ ${r.replace(' область','')}</button>`).join('')}
function bind(){document.querySelectorAll('.seg').forEach(b=>b.onclick=()=>{document.querySelectorAll('.seg').forEach(x=>x.classList.toggle('active',x===b));state.scenario=b.dataset.scenario;document.querySelectorAll('.child-only').forEach(x=>x.hidden=state.scenario!=='family');if(state.scenario!=='family')state.collections.delete('forKids');render()});document.querySelectorAll('.quick-btn').forEach(b=>b.onclick=()=>{const k=b.dataset.collection;state.collections.has(k)?state.collections.delete(k):state.collections.add(k);b.classList.toggle('active',state.collections.has(k));render()});document.querySelectorAll('.sort-btn').forEach(b=>b.onclick=()=>{state.sort=b.dataset.sort;document.querySelectorAll('.sort-btn').forEach(x=>x.classList.toggle('active',x===b));render()});document.getElementById('regionButtons').onclick=e=>{const b=e.target.closest('[data-region]');if(!b)return;const r=b.dataset.region;state.regions.has(r)?state.regions.delete(r):state.regions.add(r);b.classList.toggle('active',state.regions.has(r));b.textContent=(state.regions.has(r)?'✓ ':'✕ ')+r.replace(' область','');render()};document.querySelectorAll('[data-meal]').forEach(b=>b.onclick=()=>{const k=b.dataset.meal;const all=['none','breakfast','halfboard','fullboard'];if(state.meals.size===all.length&&state.meals.has(k)){state.meals=new Set([k])}else{state.meals.has(k)?state.meals.delete(k):state.meals.add(k)}document.querySelectorAll('[data-meal]').forEach(x=>{const on=state.meals.has(x.dataset.meal);x.classList.toggle('active',on);x.textContent=(on?'✓ ':'✕ ')+x.textContent.replace(/^[✓✕]\s*/,'')});render()});document.querySelectorAll('.wellness-btn').forEach(b=>b.onclick=()=>{const k=b.dataset.wellness;state.wellness.has(k)?state.wellness.delete(k):state.wellness.add(k);b.classList.toggle('active',state.wellness.has(k));render()});const range=document.getElementById('priceFilter');range.oninput=()=>{state.maxTotal=Number(range.value)>=Number(range.max)?Infinity:Number(range.value);document.getElementById('priceLimitLabel').textContent=Number.isFinite(state.maxTotal)?`до ${money(state.maxTotal)}`:'Без ліміту';render()}}
function matches(h,v){if(!v)return false;if(!state.regions.has(oblastOf(h)))return false;for(const k of state.collections)if(!tagsOf(h).has(k))return false;for(const k of state.wellness)if(featureState(h,k)==='no')return false;const total=v?.total7Nights||(v?.pricePerNight?v.pricePerNight*7:null);if(Number.isFinite(state.maxTotal)&&Number.isFinite(total)&&total>state.maxTotal)return false;return true}
function render(){let rows=state.data.hotels.map(h=>({...h,view:selectedView(h)})).filter(h=>matches(h,h.view));rows.sort((a,b)=>state.sort==='price'?((a.view.total7Nights||Infinity)-(b.view.total7Nights||Infinity)):state.sort==='value'?((valueNum(b.view)??-Infinity)-(valueNum(a.view)??-Infinity)):((b.view.score||0)-(a.view.score||0)));renderSummary(rows);renderCards(rows)}
function renderSummary(rows){document.getElementById('summary').innerHTML=`<span class="summary-pill result-count">Знайдено <strong>${rows.length}</strong> готелів</span><span class="summary-pill"><strong>${state.scenario==='couple'?'Удвох':'2 дорослих + дитина 10 років'}</strong></span>`}
function photoInfo(h){const rp=window.__HOTEL_PHOTO_REGISTRY__?.[h.id];if(rp)return{src:rp.src||rp.url,alt:rp.alt||h.name,source:rp.source||'перевірене джерело'};const p=h.photo;if(p&&p.status==='resolved'&&p.heroQuality!=='rejected'&&(p.src||p.url))return{src:p.src||p.url,alt:p.alt||h.name,source:p.source||'джерело готелю'};if(p&&(p.status==='missing'||p.status==='unavailable_after_search'||p.heroQuality==='rejected'))return null;return h.hero||heroImages[h.id]||null}
function setupPhoto(node,h){const media=node.querySelector('.hotel-media'),img=node.querySelector('.hotel-photo'),source=node.querySelector('.photo-source'),info=photoInfo(h);if(!info){img.removeAttribute('src');media.classList.remove('has-photo');source.textContent='Фото уточнюється';return}img.alt=info.alt||h.name;img.onload=()=>{if(img.naturalWidth>1&&img.naturalHeight>1){media.classList.add('has-photo');source.textContent='Фото: '+info.source}else{media.classList.remove('has-photo');source.textContent='Джерело не віддало реальне зображення'}};img.onerror=()=>{media.classList.remove('has-photo');source.textContent='Джерело фото недоступне — потрібна заміна'};img.src=info.src;source.textContent='Фото: перевіряється…'}
function reputationHtml(h){const r=h.reputation||{},a=[];if(r.bookingScore)a.push(`Booking <strong>${r.bookingScore}</strong>${r.bookingReviews?` · ${r.bookingReviews} відгуків`:''}`);if(r.googleScore)a.push(`Google <strong>${r.googleScore}</strong>${r.googleReviews?` · ${r.googleReviews} відгуків`:''}`);if(r.tripadvisorScore)a.push(`Tripadvisor <strong>${r.tripadvisorScore}</strong>${r.tripadvisorReviews?` · ${r.tripadvisorReviews} відгуків`:''}`);return a.map(x=>`<span>${x}</span>`).join('')}
function spaText(h){const f=h.features||h.wellness||{},parts=[];if(h.indoorSpa||f.pool===true)parts.push('критий басейн');if(f.sauna===true)parts.push('сауна');if(f.hammam===true)parts.push('хамам');if(f.jacuzzi===true)parts.push('джакузі');if(f.gym===true)parts.push('тренажерна зала');return parts.length?`<strong>SPA:</strong> ${parts.join(' · ')}`:''}
function renderCards(rows){const grid=document.getElementById('hotelGrid');grid.innerHTML='';if(!rows.length){grid.innerHTML='<div class="empty">За поточними умовами готелів не знайдено.</div>';return}rows.forEach((h,i)=>{const node=document.getElementById('hotelCardTemplate').content.cloneNode(true),v=h.view,total=v.total7Nights||(v.pricePerNight?v.pricePerNight*7:null);setupPhoto(node,h);node.querySelector('.rank-badge').textContent='#'+(i+1);node.querySelector('.hotel-name').textContent=h.name;node.querySelector('.location').textContent=`${oblastOf(h)} · ${h.location||''}`;node.querySelector('.score').textContent=(v.score||0).toFixed(1);const map=node.querySelector('.map-row');if(h.mapsUrl||h.googleMapsUrl)map.innerHTML=`<a href="${h.mapsUrl||h.googleMapsUrl}" target="_blank" rel="noopener noreferrer">Google Maps ↗</a>`;node.querySelector('.reputation').innerHTML=reputationHtml(h);node.querySelector('.week-price').textContent=money(total);node.querySelector('.night-price').textContent=`${money(v.pricePerNight)}/ніч`;node.querySelector('.meal-main').textContent=v.meals?` · ${humanize(v.meals)}`:'';const vb=node.querySelector('.value-badge');vb.hidden=true;const chips=[];const add=(label,good=false)=>{if(chips.length<8&&!chips.some(x=>x.includes('>'+label+'<')))chips.push(`<span class="chip${good?' good':''}">${label}</span>`)};const blob=[...(v.pros||[]),v.included||'',v.verdict||'',h.description||'',v.meals||''].join(' ').toLowerCase();if(tagsOf(h).has('rareFind'))add('Рідкісна знахідка',true);if(h.thermal||/термал/.test(blob))add('Термальні води');if(/солян/.test(blob))add('Соляна кімната');if(/хамам|турецьк.*парн/.test(blob))add('Хамам');if(/трираз|3-раз|повне харч/.test(blob))add('3-разове харчування');else if(/сніданок.*вечер|снідан.*\+.*вечер|двораз|2-раз/.test(blob))add('Сніданок + вечеря');else if(/снідан/.test(blob))add('Сніданок');if(/масаж/.test(blob))add('Масажі включені');if(/поїздк|екскурс/.test(blob))add('Поїздки включені');if(/велика.*територ|закрита територ|великий парк|територія.*прогуля/.test(blob))add('Велика територія');if(/серед ліс|у ліс|лісов|природн.*локац|тиха локац|тихо/.test(blob))add('Природа / тиша');if(/дитяч.*басейн/.test(blob))add('Дитячий басейн');if(/аніма|kids club|дитяч.*кімнат/.test(blob))add('Для дітей');if(/джакуз/.test(blob))add('Джакузі');if(/крит.*басейн/.test(blob))add('Критий басейн');if(/саун|парна/.test(blob))add('Сауна / парна');if(/бювет|мінеральн.*вод/.test(blob))add('Бювет / мінвода');if(/спортзал|тренажер/.test(blob))add('Спортзал');const wf=h.features||h.wellness||{};const mealMeta=h.meal||{};const familyMeta=(h.family&&h.family.eligible===undefined)?h.family:{};if(mealMeta.class==='halfboard')add('Сніданок + вечеря');else if(mealMeta.class==='breakfast')add('Сніданок');if(wf.indoorPool===true)add('Критий басейн');if(wf.childPool===true)add('Дитячий басейн');if(wf.thermalPools===true)add('Термальні води');if(wf.steamRooms===true)add('Парні');if(familyMeta.childPlayroom===true||familyMeta.playground===true)add('Для дітей');if(wf.pool===true&&!/крит.*басейн/.test(blob))add('Критий басейн');if(h.indoorSpa===true&&wf.pool!==true&&wf.indoorPool!==true&&!/крит.*басейн/.test(blob))add('Критий SPA');if(wf.hammam===true&&!/хамам|турецьк.*парн/.test(blob))add('Хамам');if(wf.jacuzzi===true&&!/джакуз/.test(blob))add('Джакузі');if(wf.sauna===true&&!/саун|парна/.test(blob))add('Сауна / парна');if(wf.gym===true&&!/спортзал|тренажер/.test(blob))add('Спортзал');if(wf.childPool===true)add('Дитячий басейн');if(wf.kidsRoom===true||wf.animation===true)add('Для дітей');if(/римськ.*парн|паров.*лазн|steam/.test(blob))add('Парна');if(/kids club|арт-клуб|дитяч.*клуб|майстер-клас|міні-кінотеатр|кінотеатр/.test(blob))add('Для дітей');if(/старе міст|музе|ботанічн.*сад|парк.*поруч|піша доступ|майстер-клас/.test(blob))add('Що подивитися поруч');if(/ресторан/.test(blob))add('Ресторан');if(/spa у комплекс|spa-центр|spa вход|spa включ|критий spa|повноцінн.*spa|spa\/wellness|басейн.*spa|spa-корпус/.test(blob))add('SPA');if(/простір для прогуля|простора територ|велика територ/.test(blob))add('Територія');if(/аквапарк/.test(blob))add('Аквапарк');if(/дитяч.*майданчик|дитяче меню/.test(blob))add('Для дітей');if(/парк історії землі|замок любарта|центр міста|центр хмельницького|тернопіль дає|кам’янець-подільський|чернівц|старе міст/.test(blob))add('Що подивитися поруч');if(/басейн.*гідромасаж|гідромасаж.*басейн/.test(blob))add('Гідромасаж');if(/сніданок і spa включ|spa у тарифі|spa входять|spa входить|spa включен|spa-access|spa access/.test(blob))add('SPA включено');if(/сімейні номери|family room|категорії 2\+1|тримісний стандарт|додаткове місце/.test(blob))add('2+1');if(/косино|берегове|винний напрям|15 км до ужгорода|близькість до ужгорода/.test(blob))add('Що подивитися поруч');if(/тренажерн.*зал|спортзал/.test(blob))add('Спортзал');if(h.nearbyAttractions===true)add('Що подивитися поруч');node.querySelector('.chips').innerHTML=chips.join('');node.querySelector('.spa-line').innerHTML=spaText(h);node.querySelector('.verdict').textContent=humanize(v.verdict);node.querySelector('.pros').innerHTML=(v.pros||[]).map(x=>`<li>${humanize(x)}</li>`).join('');node.querySelector('.cons').innerHTML=(v.cons||[]).map(x=>`<li>${humanize(x)}</li>`).join('');node.querySelector('.details').textContent=humanize(v.included||'');node.querySelector('.checked').textContent=`Перевірено: ${dateTimeFmt(h.checkedAt)}`;const a=node.querySelector('.hotel-link');a.href=h.url||'#';grid.appendChild(node)})}
load().catch(err=>{console.error(err);document.getElementById('hotelGrid').innerHTML=`<div class="empty">Не вдалося завантажити базу готелів.<br><small>${String(err?.message||err)}</small></div>`});